{
  "name": "fast-kev-compaction",
  "version": "0.6.4",
  "description": "Verbatim Kev-guided compaction for Claude Code sessions.",
  "license": "MIT",
  "userConfig": {
    "apiKey": {
      "type": "string",
      "title": "Kev API key",
      "description": "Bearer key of your Kev endpoint (the KEV_API_KEY you deployed with). Leave unset to use the KEV_API_KEY environment variable.",
      "sensitive": true
    },
    "baseUrl": {
      "type": "string",
      "title": "Kev endpoint URL",
      "description": "Required. Full URL of your Kev endpoint, e.g. https://<workspace>--kev-api.modal.run/v1/systemone."
    },
    "keepThreshold": {
      "type": "number",
      "title": "Keep threshold",
      "description": "Minimum Kev probability that a tool call or tool result is still needed; below it the item is removed.",
      "default": 0.5
    },
    "preserveRecentMessages": {
      "type": "number",
      "title": "Recent messages to preserve",
      "description": "Number of newest messages pinned from compaction.",
      "default": 6
    },
    "compactAtPercent": {
      "type": "number",
      "title": "Automatic compaction percentage",
      "description": "Context percentage at which Kev compaction starts on its own. 0 (the default) turns automatic compaction off, so it only runs when you type /kevcompact.",
      "default": 0
    },
    "minReductionRatio": {
      "type": "number",
      "title": "Minimum reduction ratio",
      "description": "Minimum estimated character reduction required to replace history.",
      "default": 0.25
    },
    "maxStateTokens": {
      "type": "number",
      "title": "Maximum Kev state tokens",
      "description": "Estimated token budget for the conversation state sent with every Kev request.",
      "default": 25000
    },
    "maxRequestTokens": {
      "type": "number",
      "title": "Maximum Kev request tokens",
      "description": "Estimated token budget for state plus questions in one Kev request.",
      "default": 30000
    },
    "truncateHeadChars": {
      "type": "number",
      "title": "Truncated tool result head",
      "description": "Characters of a tool result kept when Kev decides its full output is no longer needed; 0 keeps only the note.",
      "default": 300
    },
    "requestConcurrency": {
      "type": "number",
      "title": "Requests at once",
      "description": "How many scoring requests are in flight at once. Long conversations need many requests and the GPU answers them one after another, so keep this low (default 1, the safest).",
      "default": 1
    },
    "logDecisions": {
      "type": "boolean",
      "title": "Log every decision",
      "description": "Print one line per scored tool call to the chat (the keep and drop probabilities). Off by default because a long session produces pages of it; turn it on to see why Kev kept or dropped something.",
      "default": false
    },
    "model": {
      "type": "string",
